<template><section class="page"><div class="toolbar"><label>最近 <select v-model.number="days" @change="load"><option :value="7">7 天</option><option :value="30">30 天</option><option :value="90">90 天</option></select></label><button class="primary" @click="load">刷新</button></div><StateWrapper :loading="loading" :error="error" :empty="!data.trend.length" empty-text="暂无用量数据，完成一次问答后会显示。" @retry="load"><div class="metric-grid"><article v-for="item in metrics" :key="item.key"><small>{{ item.label }}</small><strong>{{ item.value }}</strong></article></div><div class="chart-grid"><article class="chart-card"><h3>请求与 Token 趋势</h3><TrendLine :trend="data.trend" /></article><article class="chart-card"><h3>按 Key Token 占比</h3><KeyPie :rows="data.by_key" /></article><article class="chart-card"><h3>延迟分布</h3><LatencyBar :rows="data.latency_distribution" /></article></div><p class="muted">数据由后台汇总任务刷新，最近更新时间：{{ data.summary.updated_at || '暂无' }}</p></StateWrapper></section></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import { request } from '../api'; import StateWrapper from '../components/StateWrapper.vue'; import TrendLine from '../components/charts/TrendLine.vue'; import KeyPie from '../components/charts/KeyPie.vue'; import LatencyBar from '../components/charts/LatencyBar.vue'
const days = ref(30), loading = ref(false), error = ref(''), data = ref({ summary: {}, trend: [], by_key: [], latency_distribution: [] })
const metrics = computed(() => [['total_requests', '请求数'], ['prompt_tokens', '输入 Token'], ['completion_tokens', '输出 Token'], ['p95_latency_ms', 'P95 延迟(ms)'], ['cache_hit_rate', '缓存命中率(%)'], ['error_rate', '错误率(%)']].map(([key, label]) => ({ key, label, value: data.value.summary[key] ?? 0 })))
async function load() { loading.value = true; error.value = ''; try { data.value = await request(`/api/usage/dashboard?days=${days.value}`) } catch (e) { error.value = e.message } finally { loading.value = false } }
onMounted(load)
</script>
